sys_script_client.script:
function onLoad() {
    if (!g_form.isNewRecord()) return;

    // Default Employee to the logged-in user if empty
    if (!g_form.getValue('employeename')) {
        g_form.setValue('employeename', g_user.userID());
    }

    // Populate all dependent fields from the selected employee
    populateFromEmployee(g_form.getValue('employeename'));
}

/**
 * Pulls department, employee_email, manager, manager_email
 * from the given sys_user (userSysId).
 */
function populateFromEmployee(userSysId) {
    if (!userSysId) {
        // clear if no user
        g_form.setValue('department', '');
        g_form.setValue('employee_email', '');
        g_form.setValue('manager', '');
        g_form.setValue('manager_email', '');
        return;
    }

    // 1) Get the employee record
    g_form.getReference('employeename', function(u) {
        // Email
        g_form.setValue('employee_email', u.email || '');

        // Department (u.department is the sys_id)
        if (u.department) g_form.setValue('department', u.department);

        // Manager (u.manager is sys_id). Set it, then get manager email.
        if (u.manager) {
            g_form.setValue('manager', u.manager);

            // 2) Fetch manager’s email
            var mgrField = 'manager';
            g_form.getReference(mgrField, function(m) {
                g_form.setValue('manager_email', (m && m.email) ? m.email : '');
            });
        } else {
            g_form.setValue('manager', '');
            g_form.setValue('manager_email', '');
        }
    });
}
